    Activity, 
    Settings, 
    Search,
    Plus,
    Minus,
    Maximize,
    ChevronRight,
    CircleDashed,
    LifeBuoy,
    Trash2,
    RotateCcw,
    RotateCw,
    Sliders,
    X,
    Maximize2,
    Minimize2,
    Grab
} from 'lucide-react';

const NODE_TYPES = {
    ROOT: { color: '#2563eb', icon: Settings, label: 'Central Command', level: 0 },
    DEPARTMENT: { color: '#8b5cf6', icon: Home, label: 'Dept', level: 1 },
    STAFF: { color: '#10b981', icon: Users, label: 'Staff', level: 2 },
