import React, { useState, useEffect } from 'react';
import { FileHeart, Activity, Pill, FlaskConical, Save, User as UserIcon, CheckCircle } from 'lucide-react';
import { generateBlockchainHash } from '../utils/blockchain';

export default function DoctorDashboard() {
  const doctorName = "Dr. A. Sharma";
  const [docQueue, setDocQueue] = useState([]);
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [queueRefId, setQueueRefId] = useState('');

  // High-Depth Encounter Form State
  const [chiefComplaint, setChiefComplaint] = useState('');
  const [examination, setExamination] = useState('');
  const [diagnosis, setDiagnosis] = useState('');
  const [plan, setPlan] = useState('');

  const [prescriptions, setPrescriptions] = useState([]);
  const [medInput, setMedInput] = useState({ name: '', dosage: '', frequency: '', duration: '' });

  const [labOrders, setLabOrders] = useState([]);
  const [labInput, setLabInput] = useState('');

  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchDocQueue();
  }, []);

  const fetchDocQueue = async () => {
    try {
      const resp = await fetch('http://localhost:4000/api/clinical/queue');
      if (resp.ok) {
        const data = await resp.json();
        const myPatients = data.filter(q => q.doctor === doctorName && q.status === 'Waiting for Doctor');

        // The queue endpoint now populates `patientId`, so we can extract patient data easily
        const mapped = myPatients.map(q => {
           return { ...q.patientId, queueId: q.queueId, patientId: q.patientId._id };
        });
        setDocQueue(mapped);
      }
    } catch (err) {
      console.error('Failed to fetch doctor queue', err);
    }
  };

  const handleSelectPatient = (p) => {
    setSelectedPatient(p);
    setQueueRefId(p.queueId);
    setChiefComplaint('');
    setExamination('');
    setDiagnosis('');
    setPlan('');
    setPrescriptions([]);
    setLabOrders([]);
  };

  const addMedication = () => {
     if(medInput.name) {
        setPrescriptions([...prescriptions, medInput]);
        setMedInput({ name: '', dosage: '', frequency: '', duration: '' });
     }
  };

  const addLabOrder = () => {
     if(labInput) {
        setLabOrders([...labOrders, labInput]);
        setLabInput('');
     }
  };

  const submitEncounter = async () => {
    if(!selectedPatient) return;
    setLoading(true);

    try {
       const encounterTx = {
          id: 'ENC-' + Date.now(),
          timestamp: new Date().toISOString(),
          doctorId: doctorName,
          notes: chiefComplaint + "\n" + examination,
          diagnosisCode: diagnosis,
          clinicalAction: plan
       };

       const hash = await generateBlockchainHash({ type: "CLINICAL_ENCOUNTER", mrn: selectedPatient.mrn, ...encounterTx });
       encounterTx.hash = hash;

       const updatePayload = {
          $push: {
             encounters: encounterTx
          }
       };

       if (prescriptions.length > 0) {
          updatePayload.$push.prescriptions = { timestamp: encounterTx.timestamp, prescribedBy: doctorName, medications: prescriptions, dispensed: false };
       }
       if (labOrders.length > 0) {
          updatePayload.$push.labOrders = { orderDate: encounterTx.timestamp, orderedBy: doctorName, tests: labOrders, status: 'Pending' };
       }

       // 1. Update Patient
       await fetch(`http://localhost:4000/api/clinical/patients/${selectedPatient.patientId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(updatePayload)
       });

       // 2. Update Queue Status
       await fetch(`http://localhost:4000/api/clinical/queue/${queueRefId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ status: 'Consultation Complete' })
       });

       alert("Encounter successfully hashed. Patient workflow completed. Orders dispatched:\n" + hash);
       setSelectedPatient(null);
       setQueueRefId('');
       fetchDocQueue();
    } catch(err) {
       console.error(err);
       alert("Error submitting encounter.");
    }
    setLoading(false);
  };

  const styles = {
    container: { maxWidth: '1400px', margin: '0 auto', padding: '2rem', display: 'flex', flexDirection: 'column', gap: '2rem' },
    topBar: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem' },
    title: { fontSize: '2rem', fontWeight: 700, margin: 0 },
    layout: { display: 'grid', gridTemplateColumns: 'minmax(350px, 1fr) minmax(0, 2fr)', gap: '2rem' },
    card: { background: 'var(--surface)', borderRadius: 'var(--radius)', padding: '2rem', boxShadow: 'var(--shadow-sm)', border: '1px solid var(--border)', display: 'flex', flexDirection: 'column', gap: '1rem' },
    patientItem: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '1rem', border: '1px solid var(--border)', borderRadius: 'var(--radius-sm)', cursor: 'pointer', transition: 'all 0.2s', background: 'var(--background)' },
    reportBadge: { display: 'inline-flex', alignItems: 'center', gap: '4px', fontSize: '0.75rem', background: 'var(--success-light)', color: 'var(--success)', padding: '0.25rem 0.5rem', borderRadius: 'var(--radius-sm)', fontWeight: '600' },
    inputGroup: { display: 'flex', flexDirection: 'column', gap: '0.4rem', marginBottom: '1rem' },
    input: { padding: '0.75rem', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border)', width: '100%', background: 'var(--background)', color: 'var(--text-main)', fontFamily: 'inherit' },
    rowInputs: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))', gap: '0.5rem' },
    subSection: { background: 'var(--background)', padding: '1.5rem', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border)' },
    vitalDisplay: { background: 'var(--surface)', padding: '0.5rem 1rem', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border)', fontSize: '0.85rem' }
  };

  return (
    <div style={styles.container} className="animate-fade-in-up">
      <div style={styles.topBar}>
        <div>
          <h1 style={styles.title}>Clinical Encounter Portal</h1>
          <p style={{ color: 'var(--text-muted)', margin: 0 }}>Logged in as {doctorName} - Cardiology Dept</p>
        </div>
      </div>

      <div style={styles.layout}>
        <div style={styles.card}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid var(--border)', paddingBottom: '1rem' }}>
            <h3 style={{ margin: 0 }}>My Pending Queue</h3>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', marginTop: '1rem' }}>
             {docQueue.length === 0 && <p style={{color: 'var(--text-muted)'}}>No patients currently triaged and waiting.</p>}
             {docQueue.map((p, idx) => (
                <div key={idx} style={{...styles.patientItem, borderColor: selectedPatient?.mrn === p.mrn ? 'var(--primary)' : 'var(--border)'}} onClick={() => handleSelectPatient(p)}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                    <div style={{ width: '40px', height: '40px', borderRadius: '50%', backgroundColor: 'var(--primary-light)', color: 'var(--primary)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold' }}>
                      <UserIcon size={18}/>
                    </div>
                    <div>
                      <div style={{ fontWeight: 600 }}>{p.patientName}</div>
                      <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>{p.mrn} </div>
                    </div>
                  </div>
                  <CheckCircle size={18} color="var(--success)"/>
                </div>
             ))}
          </div>
        </div>

        <div style={styles.card}>
          {!selectedPatient ? (
             <div style={{ textAlign: 'center', padding: '4rem 2rem', color: 'var(--text-muted)' }}>
                <Activity size={48} style={{ opacity: 0.3, marginBottom: '1rem' }} />
                <h3>No Clinical Focus</h3>
                <p>Select a triaged patient from your queue to begin the encounter.</p>
             </div>
          ) : (
             <div className="animate-fade-in-up">
                <div style={{ borderBottom: '1px solid var(--border)', paddingBottom: '1rem', marginBottom: '1.5rem', display: 'flex', justifyContent: 'space-between' }}>
                   <div>
                      <h2 style={{ margin: '0 0 0.5rem 0' }}>Encounter: {selectedPatient.patientName}</h2>
                      <div style={{ color: 'var(--text-muted)', fontSize: '0.9rem' }}>{selectedPatient.gender}, {selectedPatient.age} Yrs ΓÇó Blood: {selectedPatient.bloodGroup} ΓÇó MRN: {selectedPatient.mrn}</div>
                      <div style={{ color: 'var(--danger)', fontSize: '0.9rem', marginTop: '4px', fontWeight: 'bold' }}>Allergies logged: {selectedPatient.allergies || 'None'}</div>
                   </div>
                </div>

                {selectedPatient.vitals && selectedPatient.vitals.length > 0 && (
                   <div style={{ display: 'flex', gap: '1rem', marginBottom: '2rem', flexWrap: 'wrap' }}>
                      <div style={{width:'100%', fontSize:'0.85rem', fontWeight:'bold', color:'var(--text-muted)'}}>Latest Nursing Vitals:</div>
                      {Object.entries(selectedPatient.vitals[selectedPatient.vitals.length - 1]).filter(([k,v])=> v && k!=='timestamp' && k!=='hash').map(([k, v]) => (
                         <div key={k} style={styles.vitalDisplay}><strong>{k}:</strong> {v}</div>
                      ))}
                   </div>
                )}

                <h3 style={{ borderBottom: '1px solid var(--border)', paddingBottom: '0.5rem', marginBottom: '1rem' }}>Clinical Notes</h3>

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                   <div style={styles.inputGroup}>
                      <label style={{ fontWeight: 'bold', fontSize: '0.9rem' }}>Chief Complaint (HPI)</label>
                      <textarea rows="3" style={styles.input} value={chiefComplaint} onChange={e => setChiefComplaint(e.target.value)} placeholder="Patient observes..."></textarea>
                   </div>
                   <div style={styles.inputGroup}>
                      <label style={{ fontWeight: 'bold', fontSize: '0.9rem' }}>Physical Examination</label>
                      <textarea rows="3" style={styles.input} value={examination} onChange={e => setExamination(e.target.value)} placeholder="Objective findings..."></textarea>
                   </div>
                </div>

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                   <div style={styles.inputGroup}>
                      <label style={{ fontWeight: 'bold', fontSize: '0.9rem' }}>Primary Diagnosis (ICD-10)</label>
                      <input type="text" style={styles.input} value={diagnosis} onChange={e => setDiagnosis(e.target.value)} placeholder="e.g. J20.9 Acute Bronchitis" />
                   </div>
                   <div style={styles.inputGroup}>
                      <label style={{ fontWeight: 'bold', fontSize: '0.9rem' }}>Treatment Plan Details</label>
                      <input type="text" style={styles.input} value={plan} onChange={e => setPlan(e.target.value)} placeholder="Rest, hydration..." />
                   </div>
                </div>

                {/* E-Prescribing Block */}
                <div style={{...styles.subSection, marginTop: '2rem'}}>
                   <h4 style={{ margin: '0 0 1rem 0', display: 'flex', alignItems: 'center', gap: '6px' }}><Pill size={16} color="var(--primary)"/> Issue e-Prescription</h4>
                   <div style={styles.rowInputs}>
                      <input placeholder="Medicine Name" style={styles.input} value={medInput.name} onChange={e=>setMedInput({...medInput, name: e.target.value})} />
                      <input placeholder="Dosage (500mg)" style={styles.input} value={medInput.dosage} onChange={e=>setMedInput({...medInput, dosage: e.target.value})} />
                      <input placeholder="Frequency (1-0-1)" style={styles.input} value={medInput.frequency} onChange={e=>setMedInput({...medInput, frequency: e.target.value})} />
                      <input placeholder="Duration (5 Days)" style={styles.input} value={medInput.duration} onChange={e=>setMedInput({...medInput, duration: e.target.value})} />
                      <button className="btn-secondary" onClick={addMedication} style={{padding: '0.75rem'}}>Add Rx</button>
                   </div>
                   {prescriptions.length > 0 && (
                      <div style={{ marginTop: '1rem', background: 'var(--surface)', padding: '1rem', borderRadius: 'var(--radius-sm)' }}>
                         <strong>Pending Rx Dispatch:</strong>
                         <ul style={{ margin: '0.5rem 0 0 0', paddingLeft: '1.5rem', fontSize: '0.9rem' }}>
                            {prescriptions.map((px, i) => <li key={i}>{px.name} - {px.dosage} ({px.frequency}) for {px.duration}</li>)}
                         </ul>
                      </div>
                   )}
                </div>

                {/* Lab Orders Block */}
                <div style={{ ...styles.subSection, marginTop: '1rem' }}>
                   <h4 style={{ margin: '0 0 1rem 0', display: 'flex', alignItems: 'center', gap: '6px' }}><FlaskConical size={16} color="var(--purple)"/> Order Pathology / Lab Tests</h4>
                   <div style={styles.rowInputs}>
                      <select style={styles.input} value={labInput} onChange={e=>setLabInput(e.target.value)}>
                         <option value="">-- Choose Automated Order Set --</option>
                         <option>Complete Blood Count (CBC)</option>
                         <option>Comprehensive Metabolic Panel (CMP)</option>
                         <option>Lipid Profile Standard</option>
                      </select>
                      <button className="btn-secondary" onClick={addLabOrder} style={{padding: '0.75rem'}}>Add Test</button>
                   </div>
                   {labOrders.length > 0 && (
                      <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', marginTop: '1rem' }}>
                         {labOrders.map((lb, i) => <span key={i} className="badge badge-primary">{lb}</span>)}
                      </div>
                   )}
                </div>

                <div style={{ marginTop: '2.5rem' }}>
                   <button onClick={submitEncounter} disabled={loading} className="btn-primary" style={{ width: '100%', padding: '1rem', fontSize: '1.1rem' }}>
                     {loading ? 'Hashing Data Structure...' : <><Save size={18} style={{marginRight: '6px', verticalAlign:'middle'}}/> Sign & Finalize Clinical Encounter</>}
                   </button>
                </div>
             </div>
          )}
        </div>
      </div>
    </div>
  );
}

