    tabBar: { display: 'flex', gap: '1rem', marginBottom: '1.5rem' },
    tab: (active) => ({ padding: '0.75rem 1rem', background: active ? 'var(--primary)' : 'var(--background)', color: active ? 'white' : 'var(--text-main)', borderRadius: 'var(--radius-sm)', border: '1px solid', borderColor: active ? 'var(--primary)' : 'var(--border)', cursor: 'pointer', fontWeight: 'bold', flex: 1, textAlign: 'center' }),
    inputGroup: { display: 'flex', flexDirection: 'column', gap: '0.5rem', marginBottom: '1rem' },
    input: { padding: '0.75rem', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border)', width: '100%', background: 'var(--background)', color: 'var(--text-main)', fontFamily: 'inherit' }
  };

  return (
    <div style={styles.container} className="animate-fade-in-up">
      <div style={styles.header}>
        <Network size={36} color="var(--primary)" />
        <h1 style={{ margin: 0 }}>Nurse Station Operations</h1>
      </div>

      <div style={styles.grid}>
