              <div style={styles.tab(activeTab === 'transfer')} onClick={() => setActiveTab('transfer')}>Ward Config</div>
           </div>

           {activeTab === 'vitals' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                 <h3 style={{ margin: 0, borderBottom: '1px solid var(--border)', paddingBottom: '0.5rem' }}>Active Triage Queue</h3>

                 <div style={styles.inputGroup}>
                    <label style={{ fontWeight: 'bold', fontSize: '0.9rem' }}>Select Checked-in Patient</label>
                    <select style={styles.input} value={selectedQueueId} onChange={(e) => setSelectedQueueId(e.target.value)}>
                       <option value="">-- Choose Patient in Waiting Area --</option>
                       {triageQueue.map(q => (
                          <option key={q.queueId} value={q.queueId}>{q.patientName} ({q.mrn})</option>
                       ))}
                    </select>
                 </div>

                 {selectedQueueId && (
                   <div style={{ background: 'var(--background)', padding: '1.5rem', borderRadius: 'var(--radius)', border: '1px solid var(--border)' }}>
                     <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                        <div style={styles.inputGroup}>
                           <label style={{ fontSize: '0.85rem' }}><Activity size={14}/> Blood Pressure</label>
                           <input name="bloodPressure" value={vitalsData.bloodPressure} onChange={handleVitalsChange} style={styles.input} placeholder="120/80 mmHg" />
                        </div>
                        <div style={styles.inputGroup}>
                           <label style={{ fontSize: '0.85rem' }}><HeartPulse size={14}/> Heart Rate</label>
                           <input name="heartRate" value={vitalsData.heartRate} onChange={handleVitalsChange} style={styles.input} placeholder="72 bpm" />
                        </div>
                        <div style={styles.inputGroup}>
                           <label style={{ fontSize: '0.85rem' }}><Thermometer size={14}/> Temperature</label>
                           <input name="temperature" value={vitalsData.temperature} onChange={handleVitalsChange} style={styles.input} placeholder="98.6 F" />
                        </div>
                        <div style={styles.inputGroup}>
                           <label style={{ fontSize: '0.85rem' }}><Wind size={14}/> Oxygen Saturation</label>
                           <input name="oxygenSat" value={vitalsData.oxygenSat} onChange={handleVitalsChange} style={styles.input} placeholder="99 %" />
                        </div>
                     </div>
                     <button onClick={submitVitals} disabled={loading} className="btn-primary" style={{ width: '100%', marginTop: '1rem', padding: '1rem' }}>
                        {loading ? 'Securing Transaction...' : <><Save size={18} style={{marginRight: '6px', verticalAlign:'middle'}}/> Push Vitals & Route to Doctor</>}
                     </button>
                   </div>
                 )}
              </div>
           )}

           {activeTab === 'transfer' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                 <h3>Request Bed Transfer</h3>
                 <div style={styles.inputGroup}>
                    <label style={{ fontWeight: 'bold', fontSize: '0.9rem' }}>Patient MRN</label>
                    <input type="text" placeholder="MRN-XXXXXX" style={styles.input} />
                 </div>
                 <div style={styles.inputGroup}>
                    <label style={{ fontWeight: 'bold', fontSize: '0.9rem' }}>Destination Ward</label>
                    <select style={styles.input}>
                       <option>Select Ward...</option>
                       <option>ICU Floor 1</option>
                       <option>General Ward B</option>
                       <option>Emergency Level 1</option>
                    </select>
                 </div>
                 <button className="btn-primary" style={{ marginTop: '1rem', padding: '1rem' }}><BedDouble size={18} style={{ verticalAlign: 'middle', marginRight: '6px' }}/> Initiate Transfer</button>
              </div>
           )}
        </div>

        <div>
           <VisualFloorPlan wardName="Active Ward Map (Nurse Station Context)" />
        </div>
      </div>
    </div>
  );
}

