  const [prescriptionsQ, setPrescriptionsQ] = useState([]);
  const [loadingIds, setLoadingIds] = useState({});

  useEffect(() => {
    fetchPrescriptions();
  }, []);

  const fetchPrescriptions = async () => {
    try {
      const resp = await fetch('http://localhost:4000/api/clinical/patients');
      if(resp.ok) {
        const patients = await resp.json();
        const queue = [];

        patients.forEach(p => {
           if(p.prescriptions) {
              p.prescriptions.forEach((rx, idx) => {
                 // Basic Allergy Check Logic
                 const patientAllergies = (p.allergies || '').toLowerCase();

                 let hasWarning = false;
                 const parsedItems = rx.medications.map(it => {
                     let warningMsg = null;
                     const medName = it.name.toLowerCase();
                     if(patientAllergies && patientAllergies !== 'none') {
                        if(medName.includes('amoxicillin') && patientAllergies.includes('penicillin')) {
                            warningMsg = 'Cross-reactivity warning: Penicillin allergy detected.';
                        } else if (patientAllergies.includes(medName.split(' ')[0])) {
                            warningMsg = 'DIRECT CONTRAINDICATION: Patient is allergic to this.';
                        }
                     }
                     if(warningMsg) hasWarning = true;
                     return { ...it, warningMsg };
                 });

                 queue.push({
                    ...rx,
                    items: parsedItems,
                    patientName: p.patientName,
                    mrn: p.mrn,
                    allergiesLogged: p.allergies || 'None',
                    patientId: p._id,
                    patient: p, // keep a reference to patient object
                    rxIndex: idx,
                    hasWarning
                 });
              });
           }
        });

        // Sort pending first
        queue.sort((a,b) => (a.dispensed ? 1 : -1));
        setPrescriptionsQ(queue);
      }
    } catch(err) {
      console.error(err);
    }
  };

  const handleDispense = async (patient, rxIndex, encounterId, items, hasWarning) => {
    if(hasWarning) {
       const override = window.confirm("WARNING: This prescription contains a known allergen for this patient. Are you sure you want to logically override and dispense?");
       if(!override) return;
    }

    setLoadingIds({...loadingIds, [encounterId]: true});

    try {
      const dispenseRecord = {
         id: 'DISP-' + Date.now(),
         orderRef: encounterId,
         timestamp: new Date().toISOString(),
         dispensedItems: items.map(i => i.name)
      };

      const hash = await generateBlockchainHash({ type: "PHARMACY_SIG", mrn: patient.mrn, ...dispenseRecord });

      const newPrescriptions = [...patient.prescriptions];
      newPrescriptions[rxIndex].dispensed = true;
      newPrescriptions[rxIndex].dispenseHash = hash;

      await fetch(`http://localhost:4000/api/clinical/patients/${patient._id}`, {
         method: 'PUT',
         headers: {'Content-Type': 'application/json'},
         body: JSON.stringify({ prescriptions: newPrescriptions })
      });

      setInventory(prev => prev.map(med => {
         const found = items.find(it => it.name.toLowerCase().includes(med.name.split(' ')[0].toLowerCase()));
         if(found && med.stock > 0) return { ...med, stock: med.stock - 5 }; // Mock minus 5
         return med;
      }));

      alert("Dispensation verified. Stock updated. Ledger secured:\n" + hash);
      fetchPrescriptions();
    } catch(err) {
       console.error(err);
       alert("Error dispensing.");
    }
    setLoadingIds({...loadingIds, [encounterId]: false});
  };

  const styles = {
    container: { maxWidth: '1400px', margin: '0 auto', padding: '2rem' },
    header: { display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '2rem', paddingBottom: '1rem', borderBottom: '1px solid var(--border)' },
    card: { background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', padding: '1.5rem', boxShadow: 'var(--shadow-sm)' },
    grid: { display: 'grid', gridTemplateColumns: 'minmax(0, 4fr) minmax(0, 5fr)', gap: '2rem' },
    table: { width: '100%', borderCollapse: 'collapse', marginTop: '1rem' },
    th: { textAlign: 'left', padding: '1rem', borderBottom: '1px solid var(--border)', color: 'var(--text-muted)' },
    td: { padding: '1rem', borderBottom: '1px solid var(--border)', fontWeight: '500' },
    stockAlert: { color: 'white', backgroundColor: 'var(--danger)', padding: '0.2rem 0.5rem', borderRadius: 'var(--radius-full)', fontSize: '0.75rem', fontWeight: 'bold' }
  };

  return (
    <div style={styles.container} className="animate-fade-in-up">
      <div style={styles.header}>
        <Pill size={36} color="var(--primary)" />
        <h1 style={{ margin: 0 }}>Pharmacy Counter (E-Rx Queue)</h1>
      </div>

      <div style={styles.grid}>
        <div style={styles.card}>
           <h3 style={{ margin: '0 0 1rem 0' }}>Live Inventory Levels</h3>
           <table style={styles.table}>
             <thead>
               <tr>
                 <th style={styles.th}>ID</th>
                 <th style={styles.th}>Medicine Name</th>
                 <th style={styles.th}>Stock</th>
               </tr>
             </thead>
             <tbody>
               {inventory.map(med => (
                 <tr key={med.id}>
                   <td style={{ ...styles.td, color: 'var(--text-muted)' }}>{med.id}</td>
                   <td style={styles.td}>{med.name} {med.requiresPrescription && <span style={{ fontSize: '0.7rem', backgroundColor: 'var(--primary-light)', color: 'var(--primary)', padding: '2px 6px', borderRadius: '4px', marginLeft: '6px' }}>Rx</span>}</td>
                   <td style={styles.td}>
                     {med.stock < 50 ? <span style={styles.stockAlert}>{med.stock} (Low)</span> : med.stock}
                   </td>
                 </tr>
               ))}
             </tbody>
           </table>
        </div>

        <div style={styles.card}>
           <h3 style={{ margin: '0 0 1rem 0', display: 'flex', alignItems: 'center' }}><ClipboardPlus size={20} style={{ marginRight: '8px' }}/> Authorization & Dispense</h3>

           {prescriptionsQ.length === 0 ? (
               <div style={{ textAlign: 'center', padding: '4rem 2rem', color: 'var(--text-muted)' }}>
                  <Database size={32} style={{ opacity: 0.3, margin: '0 auto' }} />
                  <p>No active prescriptions right now.</p>
               </div>
           ) : (
               <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem', maxHeight: '600px', overflowY: 'auto', paddingRight: '0.5rem' }}>
                  {prescriptionsQ.map((rx, idx) => (
                     <div key={idx} style={{ padding: '1.5rem', border: `1px solid ${!rx.dispensed ? (rx.hasWarning ? 'var(--danger)' : 'var(--warning)') : 'var(--success)'}`, borderRadius: 'var(--radius)', background: !rx.dispensed ? 'var(--background)' : 'var(--surface-hover)', boxShadow: 'var(--shadow-sm)' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                           <div>
                              <div style={{ fontWeight: 'bold', fontSize: '1.1rem' }}>Patient: {rx.patientName}</div>
                              <div style={{ color: 'var(--text-muted)', fontSize: '0.85rem' }}>ENC Ref: {rx.encounterId}</div>
                           </div>
                           <div style={{ padding: '0.3rem 0.6rem', border: '1px solid var(--danger)', color: 'var(--danger)', borderRadius: 'var(--radius-sm)', fontSize: '0.8rem', fontWeight: 'bold', background: '#fef2f2' }}>
                              Allergies: {rx.allergiesLogged}
                           </div>
                        </div>

                        <div style={{ marginTop: '1.5rem', border: '1px solid var(--border)', borderRadius: 'var(--radius-sm)', overflow: 'hidden' }}>
                           <div style={{ background: 'var(--surface-hover)', padding: '0.5rem 1rem', fontSize: '0.85rem', fontWeight: 'bold', borderBottom: '1px solid var(--border)' }}>Prescription Items</div>
                           {rx.items.map((it, i) => (
                              <div key={i} style={{ padding: '1rem', borderBottom: '1px solid var(--border)', background: it.warningMsg ? '#fff1f2' : 'var(--background)' }}>
                                 <div style={{ fontWeight: 'bold' }}>{it.name} - {it.dosage}</div>
                                 <div style={{ fontSize: '0.85rem', color: 'var(--text-muted)' }}>Sig: {it.frequency} for {it.duration}</div>
                                 {it.warningMsg && (
                                    <div style={{ marginTop: '0.5rem', display: 'flex', alignItems: 'center', gap: '0.3rem', color: 'var(--danger)', fontSize: '0.85rem', fontWeight: 'bold' }}>
                                       <AlertOctagon size={14}/> {it.warningMsg}
                                    </div>
                                 )}
                              </div>
                           ))}
                        </div>

                        {!rx.dispensed ? (
                           <button onClick={() => handleDispense(rx.patient, rx.rxIndex, rx.encounterId, rx.items, rx.hasWarning)} disabled={loadingIds[rx.encounterId]} className="btn-primary" style={{ width: '100%', marginTop: '1.5rem', padding: '1rem', background: rx.hasWarning ? 'var(--danger)' : 'var(--primary)', borderColor: rx.hasWarning ? 'var(--danger)' : 'var(--primary)' }}>
                              {loadingIds[rx.encounterId] ? 'Hashing Dispensation...' : <><PackageCheck size={18} style={{verticalAlign: 'middle', marginRight: '6px'}}/> {rx.hasWarning ? 'Override Warning & Authorize' : 'Authorize & Dispense'}</>}
                           </button>
                        ) : (
                           <div style={{ marginTop: '1.5rem', padding: '1rem', background: 'var(--success-light)', border: '1px solid var(--success)', borderRadius: 'var(--radius-sm)', fontSize: '0.85rem', color: 'var(--success)', fontWeight: 'bold', wordBreak: 'break-all' }}>
                              <PackageCheck size={16} style={{verticalAlign: 'middle', marginRight: '4px'}}/> SIGNED TX HASH: {rx.dispenseHash}
                           </div>
                        )}
                     </div>
                  ))}
               </div>
           )}
        </div>
      </div>
    </div>
  );
}

