import React, { useState, useEffect } from 'react';
import { Users, Clock, ArrowRightCircle, ArrowRight } from 'lucide-react';
import { useAuth } from '../context/AuthContext';

export default function QueueDashboard() {
  const { user } = useAuth();
  const [completeQueue, setQueue] = useState([]);

  useEffect(() => {
    fetchQueue();
  }, []);

  const fetchQueue = async () => {
    try {
      const resp = await fetch('http://localhost:4000/api/clinical/queue');
      if (resp.ok) {
        const data = await resp.json();
        setQueue(data);
      }
    } catch (err) {
      console.error('Failed to fetch queue', err);
    }
  };

  const handleCall = async (queueId) => {
    try {
      const resp = await fetch(`http://localhost:4000/api/clinical/queue/${queueId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'Waiting for Vitals' })
      });
      if (resp.ok) {
         fetchQueue();
      }
    } catch (err) {
      console.error('Failed to update queue', err);
    }
  };

  const styles = {
    container: { maxWidth: '1400px', margin: '0 auto', padding: '2rem' },
    header: { display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '2rem', paddingBottom: '1rem', borderBottom: '1px solid var(--border)' },
    cols: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '2rem' },
    cardList: { background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', padding: '1.5rem', boxShadow: 'var(--shadow-sm)', display: 'flex', flexDirection: 'column', gap: '1rem' },
    patientRow: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'var(--background)', border: '1px solid var(--border)', padding: '1rem', borderRadius: 'var(--radius-sm)' }
  };

  return (
    <div style={styles.container} className="animate-fade-in-up">
      <div style={styles.header}>
        <Users size={36} color="var(--primary)" />
        <h1 style={{ margin: 0 }}>Outpatient Reception Queue</h1>
      </div>

      <div style={styles.cols}>
        <div style={styles.cardList}>
          <h3 style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', margin: '0 0 1rem 0', borderBottom: '1px solid var(--border)', paddingBottom: '0.5rem' }}>
             <Clock size={20} color="var(--primary)"/> Appointments (Booked)
          </h3>
          {completeQueue.filter(q => q.status === 'Booked').map(p => (
            <div key={p.queueId} style={styles.patientRow}>
              <div>
                <div style={{ fontWeight: 'bold' }}>{p.patientName}</div>
                <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>{p.mrn} | Date: {p.date} {p.time}</div>
                <div style={{ fontSize: '0.85rem', color: 'var(--primary)', marginTop: '0.5rem' }}>Target: {p.doctor}</div>
              </div>
              <button onClick={() => handleCall(p.queueId)} className="btn-primary" style={{ padding: '0.5rem 1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.8rem' }}>
                 Check In & Triage <ArrowRightCircle size={16}/>
              </button>
            </div>
          ))}
          {completeQueue.filter(q => q.status === 'Booked').length === 0 && <p style={{ color: 'var(--text-muted)' }}>No booked patients arriving.</p>}
        </div>

        <div style={styles.cardList}>
          <h3 style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', margin: '0 0 1rem 0', borderBottom: '1px solid var(--border)', paddingBottom: '0.5rem' }}>
             <ArrowRight size={20} color="var(--warning)"/> Waiting At Nurse Station
          </h3>
          {completeQueue.filter(q => q.status === 'Waiting for Vitals').map(p => (
            <div key={p.queueId} style={styles.patientRow}>
              <div>
                <div style={{ fontWeight: 'bold' }}>{p.patientName}</div>
                <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>{p.mrn}</div>
              </div>
              <div style={{ fontSize: '0.85rem', color: 'var(--warning)', fontWeight: 'bold' }}>Triage Pending</div>
            </div>
          ))}
          {completeQueue.filter(q => q.status === 'Waiting for Vitals').length === 0 && <p style={{ color: 'var(--text-muted)' }}>Nurse queue clear.</p>}
        </div>

        <div style={styles.cardList}>
          <h3 style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', margin: '0 0 1rem 0', borderBottom: '1px solid var(--border)', paddingBottom: '0.5rem' }}>
             <ArrowRightCircle size={20} color="var(--success)"/> Doctor Consultation
          </h3>
          {completeQueue.filter(q => q.status === 'Waiting for Doctor' || q.status === 'Consultation Complete').map(p => (
            <div key={p.queueId} style={styles.patientRow}>
              <div>
                <div style={{ fontWeight: 'bold' }}>{p.patientName} <span style={{fontSize:'0.8rem', fontWeight:'normal', color:'var(--text-muted)'}}>({p.mrn})</span></div>
                <div style={{ fontSize: '0.85rem', color: 'var(--primary)', marginTop: '4px' }}>With {p.doctor}</div>
              </div>
              <div style={{ fontSize: '0.85rem', color: p.status === 'Waiting for Doctor' ? 'var(--warning)' : 'var(--success)', fontWeight: 'bold', padding: '4px 8px', borderRadius: '4px', background: 'var(--background)', border: '1px solid var(--border)' }}>
                 {p.status}
              </div>
            </div>
          ))}
          {completeQueue.filter(q => q.status === 'Waiting for Doctor' || q.status === 'Consultation Complete').length === 0 && <p style={{ color: 'var(--text-muted)' }}>No patients in consultation.</p>}
        </div>

      </div>
    </div>
  );
}

