      <div style={styles.queueGrid}>
        {/* RED PRIORITY */}
        <div style={styles.column('var(--danger)')}>
           <h3 style={styles.colTitle}><span style={{ color: 'var(--danger)' }}>ΓùÅ</span> RED - Immediate / Resuscitation</h3>
           {patients.filter(p => p.priority === 'RED').map(p => (
             <div key={p.id} style={styles.card}>
               <div style={{ fontWeight: 'bold', fontSize: '1.1rem' }}>{p.id} | {p.name}</div>
               <div style={{ color: 'var(--danger)', fontWeight: 600, margin: '0.5rem 0' }}>{p.condition}</div>
               <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>Triaged: {p.triageTime}</div>
               <button style={{ width: '100%', padding: '0.5rem', marginTop: '0.5rem', background: '#ffe4e6', color: 'var(--danger)', border: 'none', borderRadius: 'var(--radius-sm)', fontWeight: 'bold', cursor: 'pointer' }}>Allocate ICU Bed</button>
             </div>
           ))}
        </div>

        {/* YELLOW PRIORITY */}
        <div style={styles.column('var(--warning)')}>
           <h3 style={styles.colTitle}><span style={{ color: 'var(--warning)' }}>ΓùÅ</span> YELLOW - Urgent</h3>
           {patients.filter(p => p.priority === 'YELLOW').map(p => (
             <div key={p.id} style={styles.card}>
               <div style={{ fontWeight: 'bold', fontSize: '1.1rem' }}>{p.id} | {p.name}</div>
               <div style={{ color: 'var(--warning)', fontWeight: 600, margin: '0.5rem 0' }}>{p.condition}</div>
               <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>Triaged: {p.triageTime}</div>
             </div>
           ))}
        </div>

        {/* GREEN PRIORITY */}
        <div style={styles.column('var(--success)')}>
           <h3 style={styles.colTitle}><span style={{ color: 'var(--success)' }}>ΓùÅ</span> GREEN - Minor</h3>
           {patients.filter(p => p.priority === 'GREEN').map(p => (
             <div key={p.id} style={styles.card}>
               <div style={{ fontWeight: 'bold', fontSize: '1.1rem' }}>{p.id} | {p.name}</div>
               <div style={{ color: 'var(--success)', fontWeight: 600, margin: '0.5rem 0' }}>{p.condition}</div>
               <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>Triaged: {p.triageTime}</div>
             </div>
           ))}
        </div>
      </div>
    </div>
  );
}

// Simple browser-compatible SHA-256 hash simulator for demo purposes
// In a real blockchain scenario, this would use Web3.js or equivalent to sign and broadcast the transaction.

export async function generateBlockchainHash(payloadObject) {
    const dataString = JSON.stringify(payloadObject);
    const encoder = new TextEncoder();
    const data = encoder.encode(dataString);

    // Web Crypto API
    try {
        const hashBuffer = await crypto.subtle.digest('SHA-256', data);
        const hashArray = Array.from(new Uint8Array(hashBuffer));
        const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
        return `0x${hashHex}`;
    } catch(err) {
        // Fallback if crypto isn't available
        return '0x' + Math.random().toString(16).slice(2) + Math.random().toString(16).slice(2);
    }
}
